// === Tab: mySketch ===
let simplex
let theta=0
let xNoise, yNoise
let xMove
let yMove
let scaler=1

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	 simplex = new OpenSimplexNoise(Date.now());
	xNoise= new noiseLoop(2, 2, 888)
	yNoise= new noiseLoop(3, 7, 333)
	xMove=random(22)
	yMove=random(8)

}

function draw() {
	if(scaler>0){
fill(0, 100)
	stroke(255)
	push()
	xMove+=0.12
	yMove+=0.07
	xmover= map(simplex.noise2D(xMove, frameCount/333), -9, 3, -width/11, width/33)
	ymover= map(simplex.noise2D(yMove, frameCount/222), -9, 3, -height/3, height/33)
	translate(width/2+xmover, height/2+ ymover)
	beginShape()
	scale(scaler)
	for(let i=0; i<=TAU; i+=TAU/100){
		let x= cos(i)*xNoise.value(i)
		let y= sin(i)*yNoise.value(i)
		curveVertex(x, y)
	}
	endShape(CLOSE)
	pop()
scaler-=0.00001
	}
}

class noiseLoop{

	constructor(diameter, min, max){
		this.diameter=diameter
		this.min=min
		this.max=max
	}
	value(theta){
		let xoff=map(cos(theta), -1, 1, 0, this.diameter)
		let yoff=map(sin(theta), -1, 1, 0, this.diameter)
		let r= simplex.noise3D(xoff, yoff, frameCount/100)
		return map(r, -1, 1, this.min, this.max)

	}

}

